// Retrieve data from previous nodes
const marketData = $('Market Data').first().json.data[0];
const chartData = $('Chart Data').first().json.data[0];

if (!marketData) {
  return [{ json: { error: "Market Data not available." } }];
}
if (!chartData || !chartData.prices || chartData.prices.length === 0) {
  return [{ json: { error: "Chart Data or price data not available." } }];
}

// Extract values from Market Data
const cryptoId = marketData.id || "unknown";
const currentPrice = marketData.current_price;
const priceChange24h = marketData.price_change_percentage_24h;
const totalVolume = marketData.total_volume;
const marketCap = marketData.market_cap;

// Extract historical prices from Chart Data (assumes each entry is [timestamp, price])
const prices = chartData.prices.map(entry => entry[1]);

// Optionally extract volume data from Chart Data (if available)
let volumes = [];
if (chartData.total_volumes && chartData.total_volumes.length > 0) {
  volumes = chartData.total_volumes.map(entry => entry[1]);
}

// Validate that there is enough data to compute indicators
const RSI_PERIOD = 14;
if (prices.length < RSI_PERIOD + 1) {
  return [{ json: { error: `Not enough price data to compute RSI. Need at least ${RSI_PERIOD + 1} data points.` } }];
}
const MACD_LONG = 26;
if (prices.length < MACD_LONG + 1) {
  return [{ json: { error: `Not enough price data to compute MACD. Need at least ${MACD_LONG + 1} data points.` } }];
}

/** RSI Calculation **/
function calculateRSI(prices, period = 14) {
  const gains = [], losses = [];
  for (let i = 1; i < prices.length; i++) {
    const change = prices[i] - prices[i - 1];
    gains.push(change > 0 ? change : 0);
    losses.push(change < 0 ? -change : 0);
  }
  let avgGain = 0, avgLoss = 0;
  for (let i = 0; i < period; i++) {
    avgGain += gains[i];
    avgLoss += losses[i];
  }
  avgGain /= period;
  avgLoss /= period;
  let rsi = 50;
  if (avgLoss === 0 && avgGain === 0) {
    rsi = 50;
  } else if (avgLoss === 0) {
    rsi = 100;
  } else if (avgGain === 0) {
    rsi = 0;
  } else {
    rsi = 100 - (100 / (1 + (avgGain / avgLoss)));
  }
  const rsiValues = [rsi];
  for (let i = period; i < gains.length; i++) {
    const gain = gains[i];
    const loss = losses[i];
    avgGain = ((avgGain * (period - 1)) + gain) / period;
    avgLoss = ((avgLoss * (period - 1)) + loss) / period;
    if (avgLoss === 0 && avgGain === 0) {
      rsi = 50;
    } else if (avgLoss === 0) {
      rsi = 100;
    } else if (avgGain === 0) {
      rsi = 0;
    } else {
      rsi = 100 - (100 / (1 + (avgGain / avgLoss)));
    }
    rsiValues.push(rsi);
  }
  return {
    last: rsiValues[rsiValues.length - 1],
    previous: rsiValues.length > 1 ? rsiValues[rsiValues.length - 2] : null,
    all: rsiValues
  };
}

/** MACD Calculation **/
function calculateMACD(prices, shortPeriod = 12, longPeriod = 26, signalPeriod = 9) {
  const shortK = 2 / (shortPeriod + 1);
  const longK = 2 / (longPeriod + 1);
  const signalK = 2 / (signalPeriod + 1);

  const emaShort = [];
  const emaLong = [];

  // Seed initial EMA values with a simple average
  let shortSum = 0, longSum = 0;
  for (let i = 0; i < longPeriod; i++) {
    if (i < shortPeriod) shortSum += prices[i];
    longSum += prices[i];
  }
  const initialShortEMA = shortSum / shortPeriod;
  const initialLongEMA = longSum / longPeriod;
  emaShort[shortPeriod - 1] = initialShortEMA;
  emaLong[longPeriod - 1] = initialLongEMA;

  let prevEmaShort = initialShortEMA;
  for (let i = shortPeriod; i < prices.length; i++) {
    prevEmaShort = prices[i] * shortK + prevEmaShort * (1 - shortK);
    emaShort[i] = prevEmaShort;
  }

  let prevEmaLong = initialLongEMA;
  for (let i = longPeriod; i < prices.length; i++) {
    prevEmaLong = prices[i] * longK + prevEmaLong * (1 - longK);
    emaLong[i] = prevEmaLong;
  }

  const macdLine = [];
  for (let i = longPeriod - 1; i < prices.length; i++) {
    macdLine.push(emaShort[i] - emaLong[i]);
  }

  // Compute the Signal line as the EMA of the MACD line
  const signalLine = [];
  if (macdLine.length === 0) {
    return { macd: 0, signal: 0, histogram: 0, macdLine: [], signalLine: [] };
  }
  let signalSum = 0;
  const initialSignalCount = Math.min(signalPeriod, macdLine.length);
  for (let i = 0; i < initialSignalCount; i++) {
    signalSum += macdLine[i];
  }
  let prevSignalEMA = signalSum / initialSignalCount;
  signalLine.push(prevSignalEMA);
  for (let i = initialSignalCount; i < macdLine.length; i++) {
    prevSignalEMA = macdLine[i] * signalK + prevSignalEMA * (1 - signalK);
    signalLine.push(prevSignalEMA);
  }

  const lastMACD = macdLine[macdLine.length - 1];
  const lastSignal = signalLine[signalLine.length - 1];
  const histogram = lastMACD - lastSignal;

  return {
    macd: lastMACD,
    signal: lastSignal,
    histogram: histogram,
    macdLine: macdLine,
    signalLine: signalLine,
    previousMACD: macdLine.length > 1 ? macdLine[macdLine.length - 2] : null,
    previousSignal: signalLine.length > 1 ? signalLine[signalLine.length - 2] : null
  };
}

/** Bollinger Bands Calculation **/
function calculateBollingerBands(prices, period = 20, stdDevMultiplier = 2) {
  if (prices.length < period) {
    return null;
  }
  const recentPrices = prices.slice(-period);
  const sum = recentPrices.reduce((acc, p) => acc + p, 0);
  const middle = sum / period;
  const variance = recentPrices.reduce((acc, p) => acc + Math.pow(p - middle, 2), 0) / period;
  const stdDev = Math.sqrt(variance);
  return {
    upper: middle + stdDevMultiplier * stdDev,
    middle: middle,
    lower: middle - stdDevMultiplier * stdDev
  };
}

/** Volume Analysis **/
function analyzeVolume(volumes, period = 20, minFactor = 1.5) {
  if (volumes.length === 0) {
    return null;
  }
  const recentVolumes = volumes.slice(-period);
  const avgVolume = recentVolumes.reduce((a, v) => a + v, 0) / recentVolumes.length;
  const currentVolume = volumes[volumes.length - 1];
  let trend = "Average";
  if (currentVolume > avgVolume * minFactor) {
    trend = "High";
  } else if (currentVolume < avgVolume / minFactor) {
    trend = "Low";
  }
  return { current: currentVolume, average: avgVolume, trend: trend };
}

/** Generate Trade Signal **/
function generateTradeSignal(currentPrice, priceChange24h, totalVolume, rsiObj, macdObj, bollinger, volumeAnalysis) {
  let recommendation = "Neutral";
  let explanation = [];

  const rsi = rsiObj.last;
  const rsiOversold = rsi <= 30;
  const rsiOverbought = rsi >= 70;

  const macdBullish = macdObj.previousMACD !== null && macdObj.previousSignal !== null &&
                      (macdObj.previousMACD < macdObj.previousSignal && macdObj.macd > macdObj.signal);
  const macdBearish = macdObj.previousMACD !== null && macdObj.previousSignal !== null &&
                      (macdObj.previousMACD > macdObj.previousSignal && macdObj.macd < macdObj.signal);

  if (macdBullish && rsiOversold) {
    recommendation = "Strong Buy";
    explanation.push(`RSI is ${rsi.toFixed(2)} (oversold) and MACD bullish crossover detected.`);
  } else if (macdBullish) {
    recommendation = "Buy";
    explanation.push(`MACD bullish crossover detected.`);
    if (rsi < 50 && !rsiOversold) {
      explanation.push(`RSI at ${rsi.toFixed(2)} suggests room for upside.`);
    }
  } else if (macdBearish && rsiOverbought) {
    recommendation = "Strong Sell";
    explanation.push(`RSI is ${rsi.toFixed(2)} (overbought) and MACD bearish crossover detected.`);
  } else if (macdBearish) {
    recommendation = "Sell";
    explanation.push(`MACD bearish crossover detected.`);
    if (rsi > 50 && !rsiOverbought) {
      explanation.push(`RSI at ${rsi.toFixed(2)} indicates potential for further downside.`);
    }
  } else {
    if (rsiOversold) {
      recommendation = "Potential Buy";
      explanation.push(`RSI at ${rsi.toFixed(2)} (oversold).`);
    } else if (rsiOverbought) {
      recommendation = "Potential Sell";
      explanation.push(`RSI at ${rsi.toFixed(2)} (overbought).`);
    } else {
      explanation.push(`No clear signal from RSI or MACD.`);
    }
  }

  // Include volume analysis in the explanation
  if (volumeAnalysis) {
    explanation.push(`Trading volume is ${volumeAnalysis.trend} (current: ${volumeAnalysis.current.toFixed(0)} vs average: ${volumeAnalysis.average.toFixed(0)}).`);
  }

  // Include Bollinger Bands info if available
  if (bollinger) {
    const latestPrice = prices[prices.length - 1];
    if (latestPrice < bollinger.lower) {
      explanation.push(`Price $${latestPrice.toFixed(2)} is below the lower Bollinger Band ($${bollinger.lower.toFixed(2)}), suggesting oversold conditions.`);
    } else if (latestPrice > bollinger.upper) {
      explanation.push(`Price $${latestPrice.toFixed(2)} is above the upper Bollinger Band ($${bollinger.upper.toFixed(2)}), suggesting overbought conditions.`);
    }
  }

  return { recommendation, explanation: explanation.join(" ") };
}

// Compute indicators
const rsiData = calculateRSI(prices, RSI_PERIOD);
const macdData = calculateMACD(prices, 12, 26, 9);
const bollingerData = calculateBollingerBands(prices, 20, 2);
const volumeData = analyzeVolume(volumes, 20, 1.5);

// Generate the trading signal
const tradeSignal = generateTradeSignal(currentPrice, priceChange24h, totalVolume, rsiData, macdData, bollingerData, volumeData);

// Build the result object
const result = {
  crypto: cryptoId,
  currentPrice: currentPrice,
  priceChange24h: priceChange24h,
  totalVolume: totalVolume,
  marketCap: marketCap,
  rsi: parseFloat(rsiData.last.toFixed(2)),
  rsiThresholds: { overbought: 70, oversold: 30 },
  macd: parseFloat(macdData.macd.toFixed(4)),
  macdSignal: parseFloat(macdData.signal.toFixed(4)),
  macdHistogram: parseFloat(macdData.histogram.toFixed(4)),
  macdSettings: { short: 12, long: 26, signal: 9 },
  bollinger: bollingerData ? {
    upper: parseFloat(bollingerData.upper.toFixed(4)),
    middle: parseFloat(bollingerData.middle.toFixed(4)),
    lower: parseFloat(bollingerData.lower.toFixed(4))
  } : null,
  volume: volumeData,
  tradeSignal: tradeSignal.recommendation,
  explanation: tradeSignal.explanation
};

return [{ json: result }];

/**
 * Decodes basic HTML entities in a string.
 * Converts numeric entities (e.g. &#32;) and a few named entities.
 *
 * @param {string} text - The string containing HTML entities.
 * @return {string} - The decoded string.
 */
function decodeHTMLEntities(text) {
  // Replace numeric entities
  text = text.replace(/&#(\d+);/g, (match, dec) => {
    return String.fromCharCode(dec);
  });
  // Replace some common named entities
  const entities = {
    'amp': '&',
    'lt': '<',
    'gt': '>',
    'quot': '"',
    'apos': "'",
    'nbsp': ' '
  };
  return text.replace(/&([a-zA-Z]+);/g, (match, entity) => {
    return entities[entity] || match;
  });
}

/**
 * Cleans an HTML string by removing image tags and all HTML tags,
 * then decodes HTML entities to produce plain text.
 *
 * @param {string} html - The input HTML string.
 * @return {string} - The cleaned plain text.
 */
function cleanHTML(html) {
  // Remove <img> tags (ignoring case)
  let withoutImages = html.replace(/<img[^>]*>/gi, '');

  // Remove all remaining HTML tags
  let textOnly = withoutImages.replace(/<\/?[^>]+(>|$)/g, '');

  // Decode HTML entities
  textOnly = decodeHTMLEntities(textOnly);

  // Normalize whitespace and trim the text
  return textOnly.replace(/\s+/g, ' ').trim();
}

// Process each input item
const newItems = items.map(item => {
  const inputHTML = item.json.content || "";
  const cleanedText = cleanHTML(inputHTML);
  const pubDate = item.json.pubDate;
  return { json: { cleanedText, pubDate } };
});

return newItems;
